import{_ as l,a0 as o,w as p,s as r,ao as d,I as i,x as t,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"在 CentOS 7 中安裝並使用自動化工具 Ansible | LCTT x X-CMD","titleTemplate":false,"description":"在 CentOS 7 中安裝並使用自動化工具 Ansible | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 CentOS 7 中安裝並使用自動化工具 Ansible | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 CentOS 7 中安裝並使用自動化工具 Ansible | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150930 Install and use Ansible (Automation Tool) in CentOS 7","title":"在 CentOS 7 中安裝並使用自動化工具 Ansible","tag":"201510","desc":""},"relativePath":"201510/20150930 Install and use Ansible (Automation Tool) in CentOS 7.md","filePath":"[post].md"}'),m={name:"201510/20150930 Install and use Ansible (Automation Tool) in CentOS 7.md"};function b(u,e,c,h,g,w){const n=o("Link");return p(),r("div",null,[e[13]||(e[13]=d(`<h1 id="在-centos-7-中安裝並使用自動化工具-ansible" tabindex="-1">在 CentOS 7 中安裝並使用自動化工具 Ansible <a class="header-anchor" href="#在-centos-7-中安裝並使用自動化工具-ansible" aria-label="Permalink to “在 CentOS 7 中安裝並使用自動化工具 Ansible”">​</a></h1><p>Ansible是一款為類Unix系統開發的自由開源的配置和自動化工具。它用Python寫成，類似於Chef和Puppet，但是有一個不同和優點是我們不需要在節點中安裝任何客户端。它使用SSH來和節點進行通信。</p><p>本篇中我們將在CentOS 7上安裝並配置Ansible，並且嘗試管理兩個節點。</p><ul><li><p><strong>Ansible 服務端</strong> – ansible.linuxtechi.com ( 192.168.1.15 )</p></li><li><p><strong>節點</strong> – 192.168.1.9 , 192.168.1.10</p></li></ul><h3 id="第一步-設置epel倉庫" tabindex="-1">第一步： 設置EPEL倉庫 <a class="header-anchor" href="#第一步-設置epel倉庫" aria-label="Permalink to “第一步： 設置EPEL倉庫”">​</a></h3><p>Ansible倉庫默認不在yum倉庫中，因此我們需要使用下面的命令啓用epel倉庫。</p><pre><code>[root@ansible ~]# rpm -iUvh http://dl.fedoraproject.org/pub/epel/7/x86_64/e/epel-release-7-5.noarch.rpm
</code></pre><h3 id="第二步-使用yum安裝ansible" tabindex="-1">第二步： 使用yum安裝Ansible <a class="header-anchor" href="#第二步-使用yum安裝ansible" aria-label="Permalink to “第二步： 使用yum安裝Ansible”">​</a></h3><pre><code>[root@ansible ~]# yum install ansible
</code></pre><p>安裝完成後，檢查ansible版本：</p><pre><code>[root@ansible ~]# ansible --version
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ansible-version.jpg" alt="ansible-version"></p><h3 id="第三步-設置用於節點鑑權的ssh密鑰" tabindex="-1">第三步： 設置用於節點鑑權的SSH密鑰 <a class="header-anchor" href="#第三步-設置用於節點鑑權的ssh密鑰" aria-label="Permalink to “第三步： 設置用於節點鑑權的SSH密鑰”">​</a></h3><p>在Ansible服務端生成密鑰，並且複製公鑰到節點中。</p><pre><code>root@ansible ~]# ssh-keygen
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ssh-keygen.jpg" alt="ssh-keygen"></p><p>使用ssh-copy-id命令來複制Ansible公鑰到節點中。</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ssh-copy-id-command.jpg" alt="ssh-copy-id-command"></p><h3 id="第四步-為ansible定義節點的清單" tabindex="-1">第四步：為Ansible定義節點的清單 <a class="header-anchor" href="#第四步-為ansible定義節點的清單" aria-label="Permalink to “第四步：為Ansible定義節點的清單”">​</a></h3><p>文件 <code>/etc/ansible/hosts</code> 維護着Ansible中服務器的清單。</p><pre><code>[root@ansible ~]# vi /etc/ansible/hosts
[test-servers]
192.168.1.9
192.168.1.10
</code></pre><p>保存並退出文件。</p><p>主機文件示例如下：</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ansible-host.jpg" alt="ansible-host"></p><h3 id="第五步-嘗試在ansible服務端運行命令" tabindex="-1">第五步：嘗試在Ansible服務端運行命令 <a class="header-anchor" href="#第五步-嘗試在ansible服務端運行命令" aria-label="Permalink to “第五步：嘗試在Ansible服務端運行命令”">​</a></h3><p>使用ping檢查‘test-servers’或者ansible節點的連通性。</p><pre><code>[root@ansible ~]# ansible -m ping &#39;test-servers&#39;
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ansible-ping.jpg" alt="ansible-ping"></p><h4 id="執行shell命令" tabindex="-1">執行shell命令 <a class="header-anchor" href="#執行shell命令" aria-label="Permalink to “執行shell命令”">​</a></h4><p><strong>例子1：檢查Ansible節點的運行時間（uptime）</strong></p><pre><code>[root@ansible ~]# ansible -m command -a &quot;uptime&quot; &#39;test-servers&#39;
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ansible-uptime.jpg" alt="ansible-uptime"></p><p><strong>例子2：檢查節點的內核版本</strong></p><pre><code>[root@ansible ~]# ansible -m command -a &quot;uname -r&quot; &#39;test-servers&#39;
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/kernel-version-ansible.jpg" alt="kernel-version-ansible"></p><p><strong>例子3：給節點增加用户</strong></p><pre><code>[root@ansible ~]# ansible -m command -a &quot;useradd mark&quot; &#39;test-servers&#39;
[root@ansible ~]# ansible -m command -a &quot;grep mark /etc/passwd&quot; &#39;test-servers&#39;
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/useradd-ansible.jpg" alt="useradd-ansible"></p><p><strong>例子4：重定向輸出到文件中</strong></p><pre><code>[root@ansible ~]# ansible -m command -a &quot;df -Th&quot; &#39;test-servers&#39; &gt; /tmp/command-output.txt
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/redirecting-output-ansible.jpg" alt="redirecting-output-ansible"></p><hr>`,42)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),s(n,{href:"http://www.linuxtechi.com/install-and-use-ansible-in-centos-7/"},{default:a(()=>[...e[0]||(e[0]=[t("http://www.linuxtechi.com/install-and-use-ansible-in-centos-7/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=t("作者：",-1)),s(n,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...e[2]||(e[2]=[t("Pradeep Kumar",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:a(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=t("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),s(n,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const C=l(m,[["render",b]]);export{f as __pageData,C as default};
